"""决战总览页 UI 控制器。

对应游戏 **决战地图总览页** — 从地图页「决战」面板进入。

使用方式::

    from autowsgr.ui.decisive import DecisiveBattlePage

    page = DecisiveBattlePage(ctrl, ocr=ocr)
    stage = page.recognize_stage(screen, chapter=6)
    page.enter_map()
    page.go_back()
"""

from __future__ import annotations

import re
import time
from enum import StrEnum
from typing import TYPE_CHECKING

from autowsgr.image_resources import Templates
from autowsgr.infra import ActionFailedError, DecisiveConfig, TaskStopRequested
from autowsgr.infra.logger import get_logger
from autowsgr.types import DecisiveEntryStatus, PageName
from autowsgr.ui.decisive.instructor import (
    InstructorAction,
    InstructorMatcher,
    ReplaceTarget,
    select_replace_target,
)
from autowsgr.ui.decisive.overlay import (
    CLICK_INSTRUCTOR_ACTION,
    CLICK_INSTRUCTOR_CLOSE,
    CLICK_INSTRUCTOR_NEXT,
    CLICK_INSTRUCTOR_PORTRAIT,
    CLICK_INSTRUCTOR_PREV,
    INSTRUCTOR_ACTION_AREA,
    INSTRUCTOR_NAME_AREA,
    detect_decisive_overlay,
    is_decisive_map_page,
    is_fleet_select_page,
)
from autowsgr.ui.utils import click_and_wait_for_page, confirm_operation, wait_for_stable_screen
from autowsgr.vision import (
    Color,
    ImageChecker,
    OCREngine,
    PageMatch,
    PixelChecker,
    ROI,
)
from autowsgr.vision.thresholds import TEMPLATE_LOOSE


if TYPE_CHECKING:
    import numpy as np

    from autowsgr.context import GameContext


_log = get_logger('ui.decisive')

