# 结果枚举
# ═══════════════════════════════════════════════════════════════════════════════


class ChapterResetOutcome(StrEnum):
    """章节重置结果。

    - ``RESET``：入口状态已轮询验证为「已重置」(``REFRESHED``)；
    - ``DOCK_FULL``：重置前检测到船坞已满弹窗，未消耗磁盘；
    - ``FAILED``：其它失败（确认弹窗未出现 / 超时未变为 ``REFRESHED``）。

    真值语义：仅 ``RESET`` 为真 —— 沿用 ``if not page.reset_chapter():``
    的调用方不会把失败当成功；超时落在 ``FAILED``（假值）上。
    """

    RESET = 'reset'
    """已重置，入口状态已验证为 ``REFRESHED``。"""

    DOCK_FULL = 'dock_full'
    """船坞已满，重置被拦截。"""

    FAILED = 'failed'
    """其它失败：确认弹窗未出现，或超时后入口状态仍未变为已重置。"""

    def __bool__(self) -> bool:
        return self is ChapterResetOutcome.RESET


