# 页面控制器
# ═══════════════════════════════════════════════════════════════════════════════


class DecisiveBattlePage:
    """决战总览页控制器。

    **状态查询** 为 ``staticmethod``，只需截图即可调用。
    **操作动作** 为实例方法，通过注入的控制器执行。

    Parameters
    ----------
    ctrl:
        Android 设备控制器实例。
    ocr:
        OCR 引擎实例 (可选，章节导航时需要)。
    """

    def __init__(
        self,
        ctx: GameContext,
        ocr: OCREngine | None = None,
        config: DecisiveConfig | None = None,
    ) -> None:
        self._ctx = ctx
        self._ctrl = ctx.ctrl
        self._ocr = ocr or ctx.ocr
        self._config = config or DecisiveConfig()
        self._instructor_matcher: InstructorMatcher | None = None

    # ── 页面识别 ──────────────────────────────────────────────────────────

    @staticmethod
    def is_current_page(screen: np.ndarray) -> PageMatch:
        """判断截图是否为决战总览页。

        用总览页独有的入口状态图标 (4 种: 无法出击 / 挑战中 / 已刷新 / 可重置,
        即 classic ``decisive_battle_image[3:7]``) 匹配, 命中任一即认定在总览页。
        这些图标只在总览页出现 — 全截图交叉验证其他页置信度 < 0.7, 不误命中。
        阈值 0.8 与 :meth:`detect_entry_status` 一致 (入口状态图标本身较小,
        置信度约 0.8+)。
        """
        detail = ImageChecker.find_best(
            screen, Templates.Decisive.entry_status_templates(), confidence=0.0
        )
        score = detail.confidence if detail is not None else 0.0
        name = PageName.DECISIVE_BATTLE.value
        return PageMatch(
            name=name,
            matched=score >= TEMPLATE_LOOSE,
            score=score,
            threshold=TEMPLATE_LOOSE,
        )

    # ── 小关进度识别 ──────────────────────────────────────────────────────

    @staticmethod
    def recognize_stage(screen: np.ndarray, chapter: int) -> int:
        """识别当前决战章节的小关进度 (0-3)。

        检查每个小关位置像素颜色，白色 (250,244,253) 为已通过。
        返回当前正在进行的小关编号; 3 表示全部通过。
        """
        check_points = _STAGE_CHECK_POINTS.get(chapter)
        if check_points is None:
            _log.warning('[决战] 决战 recognize_stage: 未知章节 {}', chapter)
            return 0

        for i, (rx, ry) in enumerate(check_points):
            if not PixelChecker.check_pixel(
                screen,
                rx,
                ry,
                _STAGE_CHECK_COLOR,
                _STAGE_CHECK_TOLERANCE,
            ):
                _log.info('[决战] 识别决战地图参数, 第 {} 小节正在进行', i)
                return i

        _log.info('[决战] 识别决战地图参数, 第 3 小节正在进行')
        return 3

    def detect_stage(self, screen: np.ndarray, chapter: int) -> int:
        """识别小节号（统一调用 recognize_stage）。"""
        return self.recognize_stage(screen, chapter)

    # ── 副官切换 ──────────────────────────────────────────────────────────

    def _matcher(self) -> InstructorMatcher:
        if self._instructor_matcher is None:
            self._instructor_matcher = InstructorMatcher(
                self._config.instructor_portrait_templates
            )
        return self._instructor_matcher

    def detect_current_instructor(self, screen: np.ndarray | None = None) -> str | None:
        """SIFT 识别总览页左侧立绘对应的副官。"""
        if screen is None:
            screen = self._ctrl.screenshot()
        return self._matcher().identify(screen, self._config.instructor_portrait_roi)

    def _ocr_text_in_area(
        self,
        screen: np.ndarray,
        area: tuple[float, float, float, float],
    ) -> tuple[str, tuple[int, int, int, int] | None, float]:
        roi = ROI(x1=area[0], y1=area[1], x2=area[2], y2=area[3])
        result = self._ocr.recognize_single(roi.crop(screen))
        height, width = screen.shape[:2]
        bbox = None
        if result.bbox is not None:
            x1, y1, _, _ = roi.to_absolute(width, height)
            bx1, by1, bx2, by2 = result.bbox
            bbox = (x1 + bx1, y1 + by1, x1 + bx2, y1 + by2)
        return result.text.strip(), bbox, result.confidence

    def _locate_target_on_page(
        self,
        screen: np.ndarray,
        target: str,
    ) -> ReplaceTarget | None:
        from autowsgr.vision import OCRResult

        name, name_bbox, name_confidence = self._ocr_text_in_area(screen, INSTRUCTOR_NAME_AREA)
        action, _, action_confidence = self._ocr_text_in_area(
            screen,
            INSTRUCTOR_ACTION_AREA,
        )
        # 弹窗是单页轮播：副官名在详情区、按钮在底部，二者不在同一行。
        # 这里把按钮 bbox 置空，让 select_replace_target 按“同一弹窗”处理，
        # 点击位置由调用方用固定按钮坐标兜底。
        results = [
            OCRResult(text=name, confidence=name_confidence, bbox=name_bbox),
            OCRResult(text=action, confidence=action_confidence, bbox=None),
        ]
        height, width = screen.shape[:2]
        located = select_replace_target(
            results,
            target,
            screen_width=width,
            screen_height=height,
        )
        if located is None and target and target in name:
            # 名称命中但按钮 OCR 失败时，退化为固定按钮坐标。
            return ReplaceTarget(InstructorAction.REPLACE, CLICK_INSTRUCTOR_ACTION)
        return located

    def _verify_instructor(self, target: str, *, timeout: float = 2.0) -> bool:
        """切换后轮询复核立绘，避免截图早于立绘刷新。"""
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            if self.detect_current_instructor() == target:
                return True
            if self._ctx.stop_event.wait(0.15):
                raise TaskStopRequested('决战副官复核')
        return False

    def open_instructor_panel(self) -> None:
        """点击总览页立绘打开副官弹窗，并等待名称出现。"""
        self._ctrl.click(*CLICK_INSTRUCTOR_PORTRAIT)
        wait_for_stable_screen(
            self._ctrl,
            timeout=1.5,
            interval=0.15,
            stable_frames=2,
            source='决战副官弹窗',
            stop_event=self._ctx.stop_event,
        )
        deadline = time.monotonic() + 3.0
        while time.monotonic() < deadline:
            screen = self._ctrl.screenshot()
            name, _, _ = self._ocr_text_in_area(screen, INSTRUCTOR_NAME_AREA)
            if name:
                return
            if self._ctx.stop_event.wait(0.15):
                raise TaskStopRequested('决战副官弹窗')
        raise ActionFailedError('决战副官弹窗未出现')

    def close_instructor_panel(self) -> None:
        """关闭副官弹窗。"""
        self._ctrl.click(*CLICK_INSTRUCTOR_CLOSE)
        wait_for_stable_screen(
            self._ctrl,
            timeout=1.5,
            interval=0.15,
            stable_frames=2,
            source='决战关闭副官弹窗',
            stop_event=self._ctx.stop_event,
        )

    def ensure_instructor(self, target: str) -> bool:
        """确保总览页副官为目标副官。

        先 SIFT 识别；不匹配则打开弹窗轮播定位目标，按「替换」切换。
        若目标显示「工作中」则关闭弹窗（说明已在岗）。
        切换后 SIFT 复核；仍不匹配则告警暂停。
        """
        current = self.detect_current_instructor()
        _log.info('[决战] 副官检测: 当前={}, 目标={}', current, target)
        if current == target:
            return True
        if not target:
            return True

        self.open_instructor_panel()
        try:
            for attempt in range(4):
                screen = self._ctrl.screenshot()
                located = self._locate_target_on_page(screen, target)
                if located is not None and located.action is InstructorAction.WORKING:
                    self.close_instructor_panel()
                    _log.info('[决战] 副官 {} 显示「工作中」，视为已在岗', target)
                    return True
                if located is not None and located.action is InstructorAction.REPLACE:
                    action_pos = located.click_position or CLICK_INSTRUCTOR_ACTION
                    self._ctrl.click(*action_pos)
                    wait_for_stable_screen(
                        self._ctrl,
                        timeout=2.0,
                        interval=0.15,
                        stable_frames=2,
                        source='决战替换副官',
                        stop_event=self._ctx.stop_event,
                    )
                    # 弹窗可能自动关闭；仍开着则手动关闭。
                    still_open = self._ctrl.screenshot()
                    name, _, _ = self._ocr_text_in_area(still_open, INSTRUCTOR_NAME_AREA)
                    if name:
                        self.close_instructor_panel()

                    if self._verify_instructor(target):
                        _log.info('[决战] 副官切换成功: {}', target)
                        return True
                    current = self.detect_current_instructor()
                    raise ActionFailedError(
                        f'决战副官切换后复核失败: target={target}, current={current}'
                    )

                # 前两次向右，后两次向左：即使弹窗不循环也能覆盖三名副官。
                click_pos = (
                    CLICK_INSTRUCTOR_NEXT if attempt < 2 else CLICK_INSTRUCTOR_PREV
                )
                self._ctrl.click(*click_pos)
                wait_for_stable_screen(
                    self._ctrl,
                    timeout=1.0,
                    interval=0.12,
                    stable_frames=2,
                    source='决战副官轮播',
                    stop_event=self._ctx.stop_event,
                )

            self.close_instructor_panel()
            raise ActionFailedError(f'决战副官弹窗未找到目标: {target}')
        except Exception:
            # 弹窗可能仍开着，尽量恢复总览页。
            try:
                screen = self._ctrl.screenshot()
                name, _, _ = self._ocr_text_in_area(screen, INSTRUCTOR_NAME_AREA)
                if name:
                    self.close_instructor_panel()
            except Exception:
                _log.debug('[决战] 副官弹窗恢复失败', exc_info=True)
            raise

    # ── 导航 ──────────────────────────────────────────────────────────────

    def go_back(self) -> None:
        """点击左上角 ◁，直接返回主页面 (跨级)。"""
        from autowsgr.ui.main_page import MainPage

        _log.info('[决战] 决战页面 ◁ → 主页面')
        click_and_wait_for_page(
            self._ctrl,
            click_coord=CLICK_BACK,
            checker=MainPage.is_current_page,
            source=PageName.DECISIVE_BATTLE,
            target=PageName.MAIN,
            stop_event=self._ctx.stop_event,
        )

    def click_enter_map(self) -> None:
        """从决战总览页进入当前章节的决战地图页。"""
        _log.info('[决战] 决战总览 → 进入地图')
        click_and_wait_for_page(
            self._ctrl,
            CLICK_ENTER_MAP,
            lambda screen: is_decisive_map_page(screen)
            or is_fleet_select_page(screen)
            or detect_decisive_overlay(screen) is not None,
            source='决战总览',
            target='决战地图/overlay/选船页',
            stop_event=self._ctx.stop_event,
        )

    # ── 章节 OCR ──────────────────────────────────────────────────────────

    def _read_chapter(self, screen: np.ndarray | None = None) -> int | None:
        """通过 OCR 读取当前章节编号 (Ex-N → N)。

        使用字符白名单 ``0123456789Ex-`` 提升准确率，
        避免将数字误识别为字母 (如 ``6`` → ``G``)。
        """
        if self._ocr is None:
            return None
        if screen is None:
            screen = self._ctrl.screenshot()

        x1, y1, x2, y2 = CHAPTER_NUM_AREA
        cropped = PixelChecker.crop(screen, x1, y1, x2, y2)
        result = self._ocr.recognize_single(cropped, allowlist='0123456789Ex-')
        if not result.text:
            _log.debug('[决战] 决战章节 OCR 无结果')
            return None

        m = re.search(r'(\d)', result.text[::-1])
        if m:
            chapter = int(m.group(1))
            _log.debug("[决战] 决战章节 OCR: '{}' → Ex-{}", result.text, chapter)
            return chapter

        _log.debug("[决战] 决战章节 OCR 解析失败: '{}'", result.text)
        return None

    # ── 章节导航 ──────────────────────────────────────────────────────────

    def go_prev_chapter(self) -> None:
        """点击 ◁ 切换到前一章节。"""
        _log.info('[决战] 决战页面 → 前一章节 ◁')
        self._ctrl.click(*CLICK_PREV_CHAPTER)
        wait_for_stable_screen(
            self._ctrl,
            timeout=_CHAPTER_SWITCH_DELAY,
            interval=0.1,
            stable_frames=2,
            source='决战章节切换',
            stop_event=self._ctx.stop_event,
        )

    def go_next_chapter(self) -> None:
        """点击 ▷ 切换到后一章节。"""
        _log.info('[决战] 决战页面 → 后一章节 ▷')
        self._ctrl.click(*CLICK_NEXT_CHAPTER)
        wait_for_stable_screen(
            self._ctrl,
            timeout=_CHAPTER_SWITCH_DELAY,
            interval=0.1,
            stable_frames=2,
            source='决战章节切换',
            stop_event=self._ctx.stop_event,
        )

    def navigate_to_chapter(self, target: int) -> None:
        """导航到指定决战章节。

        通过 OCR 读取当前章节编号，反复点击 ◁/▷ 直到到达目标。

        Parameters
        ----------
        target:
            目标章节编号 (MIN_CHAPTER - MAX_CHAPTER)。

        Raises
        ------
        ValueError
            章节号超出范围。
        RuntimeError
            需要 OCR 引擎但未传入。
        NavigationError
            超过最大尝试次数仍未到达。
        """
        from autowsgr.ui.utils import NavigationError

        if not MIN_CHAPTER <= target <= MAX_CHAPTER:
            raise ValueError(f'决战章节编号必须为 {MIN_CHAPTER}-{MAX_CHAPTER}，收到: {target}')
        if self._ocr is None:
            raise RuntimeError('navigate_to_chapter 需要 OCR 引擎')

        for attempt in range(_CHAPTER_NAV_MAX_ATTEMPTS):
            current = self._read_chapter()
            if current is None:
                _log.warning(
                    '[决战] 决战章节导航: OCR 识别失败 (第 {} 次尝试)',
                    attempt + 1,
                )
                wait_for_stable_screen(
                    self._ctrl,
                    timeout=_CHAPTER_SWITCH_DELAY,
                    interval=0.1,
                    stable_frames=2,
                    source='决战章节 OCR 重试',
                    stop_event=self._ctx.stop_event,
                )
                continue

            if current == target:
                _log.info('[决战] 决战章节导航: 已到达 Ex-{}', target)
                return

            if current > target:
                self.go_prev_chapter()
            else:
                self.go_next_chapter()

        raise NavigationError(
            f'决战章节导航失败: 超过 {_CHAPTER_NAV_MAX_ATTEMPTS} 次尝试, 目标 Ex-{target}',
            screen=self._ctrl.screenshot(),
        )

    # ── 磁盘购买 ─────────────────────────────────────────────────────────

    def buy_ticket(
        self,
        use: str = 'steel',
        times: int = 3,
    ) -> None:
        """购买决战磁盘 (入场券)。

        Parameters
        ----------
        use:
            资源类型: ``"oil"``/``"ammo"``/``"steel"``/``"aluminum"``。
        times:
            单次资源点击次数。

        Raises
        ------
        ValueError
            资源类型无效。
        """
        if use not in CLICK_BUY_RESOURCE:
            raise ValueError(f'资源类型必须为 oil/ammo/steel/aluminum，收到: {use}')

        _log.info('[决战] 决战页面 → 购买磁盘 (资源: {}, 次数: {})', use, times)
        self._ctrl.click(*CLICK_BUY_TICKET_OPEN)
        wait_for_stable_screen(
            self._ctrl,
            timeout=1.5,
            interval=0.1,
            stable_frames=2,
            source='决战购买磁盘-打开',
            stop_event=self._ctx.stop_event,
        )

        resource_pos = CLICK_BUY_RESOURCE[use]
        for _ in range(times):
            self._ctrl.click(*resource_pos)
            wait_for_stable_screen(
                self._ctrl,
                timeout=1.0,
                interval=0.1,
                stable_frames=2,
                source='决战购买磁盘-选择资源',
                stop_event=self._ctx.stop_event,
            )

        self._ctrl.click(*CLICK_BUY_CONFIRM)
        wait_for_stable_screen(
            self._ctrl,
            timeout=1.0,
            interval=0.1,
            stable_frames=2,
            source='决战购买磁盘-确认',
            stop_event=self._ctx.stop_event,
        )
        _log.info('[决战] 决战磁盘购买完成')

    # ── 入口状态检测 ─────────────────────────────────────────────────────

    def detect_entry_status(
        self,
        *,
        timeout: float = 10.0,
        interval: float = 0.3,
        confidence: float = 0.8,
        log: bool = True,
    ) -> DecisiveEntryStatus:
        """检测当前决战总览页的入口状态。

        通过图像模板匹配识别 4 种入口状态:
        ``CANT_FIGHT`` / ``CHALLENGING`` / ``REFRESHED`` / ``REFRESH``。

        对应 legacy ``detect('enter_map')`` — 使用
        ``decisive_battle_image[3:7]`` 的 ``wait_images``。

        Parameters
        ----------
        timeout:
            最大等待时间 (秒)。
        interval:
            截图检测间隔 (秒)。
        confidence:
            模板匹配置信度阈值。
        log:
            命中时是否打 info 日志。轮询场景 (如 :meth:`reset_chapter`)
            关闭它，避免同一状态每轮刷屏。

        Returns
        -------
        DecisiveEntryStatus
            检测到的入口状态枚举值。

        Raises
        ------
        TimeoutError
            超时仍未匹配到任何入口状态。
        """
        from autowsgr.image_resources import Templates

        templates = Templates.Decisive.entry_status_templates()
        statuses = list(DecisiveEntryStatus)

        deadline = time.monotonic() + timeout
        while True:
            screen = self._ctrl.screenshot()
            detail = ImageChecker.find_any(
                screen,
                templates,
                confidence=confidence,
            )
            if detail is not None:
                idx = next(i for i, t in enumerate(templates) if t.name == detail.template_name)
                status = statuses[idx]
                if log:
                    _log.info('[决战] 决战入口状态: {}', status.value)
                return status

            if time.monotonic() >= deadline:
                raise TimeoutError(f'检测决战入口状态超时 ({timeout}s): 未匹配到任何状态模板')
            if self._ctx.stop_event.wait(interval):
                raise TaskStopRequested('检测决战入口状态')

    # ── 章节重置 ─────────────────────────────────────────────────────────

    def reset_chapter(
        self,
        *,
        timeout: float = 10.0,
        interval: float = 0.5,
    ) -> ChapterResetOutcome:
        """使用磁盘重置当前章节，并验证入口状态确实变为「已重置」。

        流程: 点「重置关卡」→ 等画面稳定 → 船坞满检查 → 点确认 →
        轮询 :meth:`detect_entry_status` 直到 ``REFRESHED``。

        Parameters
        ----------
        timeout:
            点击确认后等待入口状态变为 ``REFRESHED`` 的最长时间 (秒)。
        interval:
            两次入口状态检测之间的间隔 (秒)。

        Returns
        -------
        ChapterResetOutcome
            三种结果：``RESET`` / ``DOCK_FULL`` / ``FAILED``。``FAILED``
            是假值 — 对应原契约「超时返回 False」。

        Raises
        ------
        TaskStopRequested
            轮询期间收到任务停止信号。

        Notes
        -----
        调用前需确保已在决战总览页且已导航到目标章节。
        """
        _log.info('[决战] 决战页面 → 重置关卡')
        self._ctrl.click(*CLICK_RESET_CHAPTER)
        wait_for_stable_screen(
            self._ctrl,
            timeout=1.0,
            interval=0.1,
            stable_frames=2,
            source='决战重置关卡-弹窗',
            stop_event=self._ctx.stop_event,
        )
        screen = self._ctrl.screenshot()
        if ImageChecker.template_exists(
            screen,
            Templates.Build.SHIP_FULL_DEPOT,
            confidence=0.8,
        ):
            _log.warning('[决战] 重置关卡时检测到船坞已满')
            return ChapterResetOutcome.DOCK_FULL

        if not confirm_operation(self._ctrl, must_confirm=False, timeout=5.0):
            # 磁盘不足 / 网络重试 / 弹窗变体都会走到这里：确认按钮根本没出现。
            _log.error('[决战] 重置关卡：未等到确认按钮（磁盘不足或被弹窗拦截）')
            return ChapterResetOutcome.FAILED

        # 确认后入口应当变成「已重置」。轮询而不是睡固定时长：
        # 点击未生效、点击落到别处、磁盘不足时状态会一直停在「可重置」。
        deadline = time.monotonic() + max(timeout, 0.0)
        last_status: DecisiveEntryStatus | None = None
        while True:
            try:
                status = self.detect_entry_status(
                    timeout=0.0,
                    interval=interval,
                    log=False,
                )
            except TimeoutError:
                status = None
            if status is not None and status is not last_status:
                _log.info('[决战] 重置轮询: 入口状态={}', status.value)
                last_status = status

            if status is DecisiveEntryStatus.REFRESHED:
                # 已重置后画面还可能残留动画，等稳定再交给后续 stage 识别。
                wait_for_stable_screen(
                    self._ctrl,
                    timeout=1.0,
                    interval=0.1,
                    stable_frames=2,
                    source='决战重置关卡-已重置',
                    stop_event=self._ctx.stop_event,
                )
                _log.info('[决战] 决战关卡重置完成（入口状态=已重置）')
                return ChapterResetOutcome.RESET

            if time.monotonic() >= deadline:
                break
            if self._ctx.stop_event.wait(interval):
                raise TaskStopRequested('决战重置关卡确认')

        _log.error(
            '[决战] 重置关卡失败：{:.1f}s 内入口状态未变为「已重置」（最后观测: {}）',
            timeout,
            last_status.value if last_status is not None else '无匹配',
        )
        return ChapterResetOutcome.FAILED
